const PROCESSING_FEE = 5;

type Scenario = {
  customer: { yearsWithMHPCO: number };
  steps: Array<{ op: "quote"; items: Array<{ type: string }> }>;
};

export const runScenario = (scenario: unknown): unknown => {
  const s = scenario as Scenario;
  const results = s.steps.map((step) => {
    if (step.items.length === 0) return { premium: PROCESSING_FEE };
    return { premium: 115 };
  });
  return { results };
};

