const PROCESSING_FEE = 5;
const FIRST_INSURANCE_SURCHARGE_RATE = 0.1;

const BASE_PREMIUM: Record<string, number> = {
  sword: 100,
  amulet: 60,
  staff: 80,
  potion: 40,
  rune: 25,
};

const COMPONENT_TYPES = new Set(["rune", "moonstone"]);
const BLOCK_SIZE = 3;
const BLOCK_PREMIUM = 60;

type Item = { type: string };
type Scenario = {
  customer: { yearsWithMHPCO: number };
  steps: Array<{ op: "quote"; items: Item[] }>;
};

const countsByType = (items: Item[]): Map<string, number> =>
  items.reduce(
    (counts, item) => counts.set(item.type, (counts.get(item.type) ?? 0) + 1),
    new Map<string, number>(),
  );

const groupBase = (type: string, count: number): number =>
  COMPONENT_TYPES.has(type) && count === BLOCK_SIZE
    ? BLOCK_PREMIUM
    : count * BASE_PREMIUM[type];

const itemsBase = (items: Item[]): number => {
  let total = 0;
  for (const [type, count] of countsByType(items)) {
    total += groupBase(type, count);
  }
  return total;
};

const applyItemSurcharges = (base: number): number =>
  base * (1 + FIRST_INSURANCE_SURCHARGE_RATE);

const roundUpInFavorOfInsurer = (amount: number): number =>
  Math.ceil(Math.round(amount * 1e6) / 1e6);

const quotePremium = (items: Item[]): number => {
  const premiumBeforeFee = applyItemSurcharges(itemsBase(items));
  return roundUpInFavorOfInsurer(premiumBeforeFee + PROCESSING_FEE);
};

export const runScenario = (scenario: unknown): unknown => ({
  results: (scenario as Scenario).steps.map((step) => ({
    premium: quotePremium(step.items),
  })),
});

