const isCursed = (item: Item): boolean => item.cursed === true;
const isHighlyEnchanted = (item: Item): boolean =>
  (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_THRESHOLD;

const itemSurcharge = (item: Item): number => {
  const base = BASE_PREMIUM[item.type];
  const curseSurcharge = isCursed(item) ? base * CURSE_SURCHARGE_RATE : 0;
  const highEnchantmentSurcharge = isHighlyEnchanted(item)
    ? base * HIGH_ENCHANTMENT_SURCHARGE_RATE
    : 0;
  return curseSurcharge + highEnchantmentSurcharge;
};

const itemSurchargesTotal = (items: Item[]): number =>
  items.reduce((sum, item) => sum + itemSurcharge(item), 0);

const roundUpInFavorOfInsurer = (amount: number): number =>
  Math.ceil(Math.round(amount * 1e6) / 1e6);

const quotePremium = (items: Item[]): number => {
  const policyBase = itemsBase(items);
  const firstInsuranceSurcharge = policyBase * FIRST_INSURANCE_SURCHARGE_RATE;
  const itemSurcharges = itemSurchargesTotal(items);
  return roundUpInFavorOfInsurer(policyBase + itemSurcharges + firstInsuranceSurcharge + PROCESSING_FEE);
};

export const runScenario = (scenario: unknown): unknown => ({
  results: (scenario as Scenario).steps.map((step) => ({
    premium: quotePremium(step.items),
  })),
});

