  const s = scenario as Scenario;
  const policies = new Map<number, PolicyState>();
  let quoteCount = 0;
  const results: StepResult[] = s.steps.map((step, index) => {
    if (step.op === "quote") {
      const isFollowUp = quoteCount > 0;
      quoteCount += 1;
      policies.set(index, createPolicy(step.items));
      return { premium: quotePremium(step.items, s.customer, isFollowUp) };
    }
    const policy = policies.get(step.policy)!;
    return processClaim(policy, step.incident.damages);
  });
  return { results };
};

